"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.3 stimulus renderer (sections 3-4): one item spec -> its versions (N, E, Y) as 8 s windows at 16 kHz.

Deterministic given the spec. Speech (TTS), event and decoy are convolved with RIRs from the item's room; background
noise is a DEMAND segment at the spec's SNR. The base (noise + speech) is the N version; E and Y add the event or decoy
on top, so all versions are sample-identical outside [event start, event end + reverb tail], which is checked on the
int16 output (+-1 LSB). Levels: speech active RMS = REF; event and decoy active RMS = REF * 10^(rel_db/20) after
reverb (the same rel_db, duration, gap, onset, room position and fades for E and Y). If a version would clip, only the
added event or decoy is lowered and this is recorded.

Window: the decision point (end of the user's line + 0.2 s) is the last sample of the 8 s window.
"""
import hashlib
import os
import re

import numpy as np
import soundfile as sf
from scipy.signal import fftconvolve, resample_poly

SR = 16000
WIN = 8 * SR
REF = 0.05                    # speech active RMS (about -26 dBFS)
FADE = int(0.02 * SR)
TTS_CACHE = "data/p1/tts_cache"
_kokoro = None
_piper = None


def resample(x, sr):
    if sr == SR:
        return x.astype(np.float32)
    g = np.gcd(int(sr), SR)
    return resample_poly(x, SR // g, int(sr) // g).astype(np.float32)


def load_mono(path):
    x, sr = sf.read(path, dtype="float32", always_2d=True)
    return resample(x.mean(1), sr)


def frame_db(x, frame=320):
    n = len(x) // frame
    if n == 0:
        return np.array([-120.0])
    e = (x[:n * frame].reshape(n, frame) ** 2).mean(1)
    return 10 * np.log10(e + 1e-12)


def active_rms(x, frame=320, rel_db=-30.0):
    d = frame_db(x, frame)
    act = d > d.max() + rel_db
    n = len(d)
    seg = x[:n * frame].reshape(n, frame)[act]
    return float(np.sqrt((seg ** 2).mean())) if seg.size else float(np.sqrt((x ** 2).mean()) + 1e-9)


def active_span(x, frame=320, rel_db=-35.0):
    """(first, last) sample of frames within rel_db of the loudest frame."""
    d = frame_db(x, frame)
    idx = np.nonzero(d > d.max() + rel_db)[0]
    return int(idx[0] * frame), int((idx[-1] + 1) * frame)


def crop(x, dur_s, rng):
    """A segment of dur_s seconds inside the clip's active span (None if the span is shorter), with 20 ms fades."""
    a, b = active_span(x)
    n = int(dur_s * SR)
    if b - a < n:
        return None
    s = int(rng.integers(a, b - n + 1))
    y = x[s:s + n].copy()
    ramp = np.linspace(0, 1, FADE, dtype=np.float32)
    y[:FADE] *= ramp
    y[-FADE:] *= ramp[::-1]
    return y


def reverb(x, rir_path):
    h = load_mono(rir_path)
    h = h / (np.abs(h).max() + 1e-9)
    return fftconvolve(x, h).astype(np.float32)


def at_level(x, rms):
    return (x * (rms / (active_rms(x) + 1e-9))).astype(np.float32)


def tts(text, voice, engine="kokoro", speaker=None):
    """16 kHz TTS audio, cached on disk by (engine, voice, speaker, text)."""
    os.makedirs(TTS_CACHE, exist_ok=True)
    key = hashlib.sha1(f"{engine}|{voice}|{speaker}|{text}".encode("utf-8")).hexdigest()[:16]
    path = os.path.join(TTS_CACHE, key + ".npy")
    if os.path.exists(path):
        return np.load(path)
    if engine == "kokoro":
        global _kokoro
        if _kokoro is None:
            import torch
            from kokoro import KModel, KPipeline
            snap = os.path.join(os.path.expanduser("~"), ".cache", "huggingface", "hub", "models--hexgrad--Kokoro-82M",
                                "snapshots", "f3ff3571791e39611d31c381e3a41a3af07b4987")
            model = KModel(repo_id="hexgrad/Kokoro-82M", config=os.path.join(snap, "config.json"),
                           model=os.path.join(snap, "kokoro-v1_0.pth")).to("cpu").eval()
            pipes = {lc: KPipeline(lang_code=lc, repo_id="hexgrad/Kokoro-82M", model=model, device="cpu")
                     for lc in ("a", "b")}
            _kokoro = (torch, snap, pipes)
        torch, snap, pipes = _kokoro
        torch.manual_seed(0)
        pipe = pipes["b" if voice.startswith("b") else "a"]
        parts = [r.audio.numpy() for r in pipe(text, voice=os.path.join(snap, "voices", f"{voice}.pt"))
                 if r.audio is not None]
        x = resample(np.concatenate(parts), 24000)
    elif engine == "piper":                              # unseen second engine: Piper en_US-libritts-high, 22.05 kHz
        global _piper
        if _piper is None:
            from piper import PiperVoice, SynthesisConfig
            _piper = (PiperVoice.load("data/models_dl/piper_libritts_high_6b9cfaa/en/en_US/libritts/high/"
                                      "en_US-libritts-high.onnx"), SynthesisConfig)
        pv, cfg = _piper
        chunks = list(pv.synthesize(text, syn_config=cfg(speaker_id=int(speaker))))
        x = resample(np.concatenate([c.audio_float_array for c in chunks]), chunks[0].sample_rate)
    else:
        raise NotImplementedError(engine)
    a, b = active_span(x, rel_db=-40.0)
    x = x[max(0, a - int(0.03 * SR)):b + int(0.03 * SR)]
    tmp = path[:-4] + f".tmp{os.getpid()}.npy"           # atomic: parallel workers never read a half-written file
    np.save(tmp, x)
    try:
        os.replace(tmp, path)
    except OSError:
        if os.path.exists(tmp):
            os.remove(tmp)
    return x


def noise_segment(env_path, offset_s, n):
    x, sr = sf.read(env_path, dtype="float32", start=int(offset_s * 16000), frames=n)
    if x.ndim > 1:
        x = x.mean(1)
    return resample(x, sr)[:n]


def place(buf, x, start):
    """Add x into buf starting at sample `start` (may be negative); returns the touched span."""
    a, b = max(0, start), min(len(buf), start + len(x))
    if b > a:
        buf[a:b] += x[a - start:b - start]
    return a, b


def render(spec, rng=None):
    """Returns ({version: int16 array}, meta). spec keys: see scripts/p1_plan_items.py."""
    rng = rng or np.random.default_rng(spec["seed"])
    noise = noise_segment(spec["noise_path"], spec["noise_offset_s"], WIN)
    noise *= (REF / 10 ** (spec["snr_db"] / 20)) / (np.sqrt((noise ** 2).mean()) + 1e-9)
    base = noise.astype(np.float32).copy()
    end_line = WIN - int(0.2 * SR)
    meta = {"item_id": spec["item_id"]}

    speech = at_level(reverb(tts(spec["line"], spec["user_voice"], spec.get("engine", "kokoro"),
                                 spec.get("piper_speaker")), spec["rir_speech"]),
                      REF * 10 ** (spec.get("speech_rel_db", 0.0) / 20))
    dry_len = len(tts(spec["line"], spec["user_voice"], spec.get("engine", "kokoro"), spec.get("piper_speaker")))
    line_start = end_line - dry_len
    place(base, speech, line_start)
    meta["line_start_s"], meta["line_end_s"] = line_start / SR, end_line / SR

    if spec.get("family_line"):                          # F3: a family member calls from another room (E only)
        fam = at_level(reverb(tts(spec["family_line"], spec["family_voice"]), spec["rir_family"]),
                       REF * 10 ** (spec["family_rel_db"] / 20))

    if spec["cell"] in ("D", "Dk"):                      # the event starts while the user is asking
        frac = spec.get("event_onset_in_line_frac")
        onset = line_start + (int(frac * dry_len) if frac is not None else int(spec["event_onset_in_line_s"] * SR))
    else:
        onset = line_start - int(spec["gap_s"] * SR) - int(spec["event_dur_s"] * SR)
    versions = {"N": base}
    spans = {}
    for v, key in (("E", "event"), ("Y", "decoy")):
        if v not in spec["versions"] or not spec.get(key):
            continue
        x = crop(load_mono(spec[key]["path"]), spec["event_dur_s"], np.random.default_rng(spec["seed"] + (v == "Y")))
        if x is None:
            raise ValueError(f"{spec['item_id']}: {key} clip shorter than {spec['event_dur_s']} s")
        wet = at_level(reverb(x, spec["rir_event"]), REF * 10 ** (spec["event_rel_db"] / 20))
        out, gain = base.copy(), 1.0
        for _ in range(40):
            trial = base.copy()
            place(trial, wet * gain, onset)
            if np.abs(trial).max() <= 0.98:
                out = trial
                break
            gain *= 0.9
        versions[v] = out
        spans[v] = (max(0, onset), min(WIN, onset + len(wet)))
        meta[f"{v}_gain_reduced_db"] = round(-20 * np.log10(gain), 2)
    if spec.get("family_line") and "E" in spec["versions"]:
        e = base.copy()
        fam_start = line_start - int(spec["gap_s"] * SR) - len(tts(spec["family_line"], spec["family_voice"]))
        place(e, fam, fam_start)
        versions["E"] = e
        spans["E"] = (max(0, fam_start), min(WIN, fam_start + len(fam)))
    if "N" not in spec["versions"]:
        versions.pop("N")
    peak = max(float(np.abs(x).max()) for x in versions.values())
    if peak > 0.99:
        raise ValueError(f"{spec['item_id']}: clipping in the base mix (peak {peak:.2f})")
    out = {v: np.round(np.clip(x, -1, 1) * 32767).astype(np.int16) for v, x in versions.items()}
    if "N" in out:
        for v, (a, b) in spans.items():
            d = np.abs(out[v].astype(np.int32) - out["N"].astype(np.int32))
            d[a:b] = 0
            assert d.max() <= 1, f"{spec['item_id']}: {v} differs from N outside the event span"
    meta["spans_s"] = {v: (a / SR, b / SR) for v, (a, b) in spans.items()}
    meta["event_onset_s"] = onset / SR
    return out, meta


def write(out_dir, item_id, versions):
    os.makedirs(out_dir, exist_ok=True)
    paths = {}
    for v, x in versions.items():
        p = os.path.join(out_dir, f"{item_id}_{v}.wav")
        sf.write(p, x, SR, subtype="PCM_16")
        paths[v] = p
    return paths


def safe_id(s):
    return re.sub(r"[^A-Za-z0-9_.-]+", "_", s)
